INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ignoriere ich hier die Prozessanalyse?', 2, '[{"text": "Nein", "correct": true, "because": "Value Stream Mapping ist zentral"}, {"text": "Ja", "correct": false, "because": "Prozesse werden analysiert"}]'),
