('00000000-0000-0000-0000-000000000000', 'Welche Techniken fördern die Optimierung?', 5, '[{"text": "Value Stream Mapping", "correct": true, "because": "Verschwendung erkennen"}, {"text": "Build-Measure-Learn", "correct": true, "because": "Lernen und anpassen"}, {"text": "Manuelle Prozesse", "correct": false, "because": "Effizienz zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Build-Measure-Learn nutzt Feedback. b) Value Stream Mapping ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mapping essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Methoden?', 4, '[{"text": "Value Stream Mapping", "correct": false, "because": "Prozesse analysieren"}, {"text": "Build-Measure-Learn", "correct": false, "because": "Lernzyklen nutzen"}, {"text": "Unstrukturierte Arbeit", "correct": true, "because": "Struktur zählt"}]'),
